import * as storage from './storage.js';
import {dayKey,skills,dueTasks,plan,updateProgress} from './scheduler.js';
import {choices} from './quiz.js';
import * as audio from './audio.js';
const $=s=>document.querySelector(s),app=$('#app'),notice=$('#notice');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cards=[],byId,state=storage.initial(),persistent=true,busy=false,shownOptions=[],pendingImport=null;
document.addEventListener('audio-error',e=>tell(e.detail));
const channel=typeof BroadcastChannel==='function'?new BroadcastChannel('english-stage'):null;
channel?.addEventListener('message',async()=>{if(!busy&&persistent){state=await storage.read();render();}});
function tell(s){notice.textContent=s;}
async function mutate(fn){
 if(busy)return;busy=true;
 const run=async()=>{if(persistent)state=await storage.read();fn(state);if(persistent)try{await storage.write(state);channel?.postMessage('saved');}catch{persistent=false;tell('保存できませんでした。この回の記録は一時的です。設定からバックアップしてください。');}};
 try{if(navigator.locks)await navigator.locks.request('english-stage-write',run);else await run();}catch(e){tell(e.message);}finally{busy=false;render();}
}
const skillLabel={read:'読んでわかる',listen:'聞いてわかる',recall:'日本語から英語',self:'自分で思い出す'};
function progress(c){const p=state.progress[c.id]||{};return skills.every(k=>p[k]?.mastered)?'定着してきた':skills.some(k=>p[k]?.correct)?'思い出せた':state.seen[c.id]?'練習中':'これから';}
function go(hash){location.hash=hash;}
function image(c){return c.image?`<img class="picture" src="${esc(c.image.url)}" alt="${esc(c.ja)}" referrerpolicy="no-referrer"><small class="image-credit">${esc(c.image.credit)}</small>`:visual(c);}
function visual(c){const n=['one','two','three','four','five','six','seven','eight','nine','ten'].indexOf(c.en);if(n>=0)return `<div class="visual" aria-label="${n+1}">${n+1}</div>`;const colors={red:'#d76b63',blue:'#779fc5',green:'#729a77',yellow:'#e4c159',white:'#fff',black:'#333'};if(colors[c.en])return `<div class="visual"><span style="width:85px;height:85px;background:${colors[c.en]};border:1px solid #ddd;border-radius:50%"></span></div>`;if(/It's (on|under|in) /.test(c.en)){const pos=c.en.match(/It's (\w+)/)[1];return `<svg role="img" aria-label="${esc(c.ja)}" viewBox="0 0 240 150" width="240" height="150">${pos==='in'?'<rect x="65" y="35" width="110" height="100" rx="8" fill="#d5e1cf" stroke="#526b52" stroke-width="3"/><path d="M90 35V20H150V35" fill="none" stroke="#526b52" stroke-width="3"/>':'<path d="M40 55H200M60 55V135M180 55V135" fill="none" stroke="#526b52" stroke-width="7"/>'}<circle cx="120" cy="${pos==='on'?40:pos==='in'?85:112}" r="12" fill="#db9c48"/></svg>`;}return `<div class="visual" aria-hidden="true">${c.kind==='phrase'?'“ ”':'Aa'}</div>`;}
const audioButtons=(example=true)=>`<div class="audio-controls"><button data-audio="normal">▶ もう一度</button><button data-audio="slow">ゆっくり</button>${example?'<button data-audio="example">例文を聞く</button>':''}<button data-stop>■ 停止</button></div>`;
function cardBody(c){return `<div class="eyebrow">${esc(c.theme)} · ${c.kind==='word'?'WORD':'PHRASE'}</div>${image(c)}<div class="card-en" lang="en-US">${esc(c.en)}</div><div class="card-ja">${esc(c.ja)}</div>${audioButtons()}<div class="example"><p lang="en-US">${esc(c.example)}</p><p>${esc(c.exampleJa)}</p></div><p class="muted">${esc(c.explanation)}</p>`;}
function home(){
 const due=dueTasks(cards,state).length,learned=Object.keys(state.seen).length,newN=Math.min(due>=10?0:state.settings.newCount,cards.length-learned),days=new Set(state.history.map(h=>dayKey(h.at))).size;
 app.innerHTML=`<div class="home-grid"><section class="hero"><div class="eyebrow">A little English, every day</div><h1>ひとつわかると、<br>世界がちょっと広がる。</h1><p>絵でわかる。音でつながる。<br>きのうのことばを、きょうの自信に。</p><div class="today"><span class="pill">新しく ${newN}こ</span><span class="pill">復習 ${Math.min(due,12)}問${due>12?'ずつ':''}</span></div><button class="primary start" id="start">${state.session?'つづきからはじめる':'きょうの10分をはじめる'} <span>→</span></button><p><small>1回20ステップまで。途中で休んでも大丈夫。</small></p></section><aside class="stage"><span class="spark">✧</span><div class="stage-art"><div class="stage-card">${state.stars>=30?'✦':'A'}</div><div class="stage-card">${state.stars>=10?'✿':'a'}</div></div><div class="stage-label">YOUR LITTLE STAGE</div><p>✦ ${state.stars} stars <small> · 次の飾りまで ${state.stars<10?10-state.stars:state.stars<30?30-state.stars:0}こ</small></p><small>取り組むたびに、ステージが育つ。</small></aside></div><div class="stats"><div class="stat"><strong>${learned}</strong><span>出会ったことば / 130</span></div><div class="stat"><strong>${days}</strong><span>学んだ日</span></div><div class="stat"><strong>${cards.filter(c=>progress(c)==='定着してきた').length}</strong><span>定着してきたことば</span></div></div><div class="section-head"><h2>自分のペースで、もう少し。</h2><a href="#alphabet">ABCから確かめる ↗</a></div><div class="tiles"><a class="tile" href="#library"><span class="icon">▤</span><strong>ことば帳をひらく →</strong><p>100語と30表現。気になることばから。</p></a><button class="tile" id="mistakes"><span class="icon">↻</span><strong>まちがえたもの →</strong><p>意味と音を確かめて、もう一度。</p></button><a class="tile" href="#learned"><span class="icon">✧</span><strong>できるようになったもの →</strong><p>小さな成長を見つけよう。</p></a></div>`;
 $('#start').onclick=()=>{if(state.session)go('study');else start('daily');};$('#mistakes').onclick=()=>start('mistakes');
}
async function start(mode){await mutate(s=>{const tasks=plan(cards,s,mode);s.session={id:crypto.randomUUID(),tasks,index:0,tries:{},feedback:null,started:Date.now(),answered:0,newSeen:0,correct:0,recovered:0,mode};});go('study');}
function sessionDone(s){return s.index>=s.tasks.length||s.answered>=20||Date.now()-s.started>=600000;}
function study(){
 const s=state.session;if(!s){app.innerHTML='<div class="empty"><h1>今日も、少しずつ。</h1><a href="#home">ホームへ</a></div>';return;}
 if(sessionDone(s)&&!s.feedback){app.innerHTML=`<div class="narrow panel card"><div class="check">✦</div><div class="eyebrow">Nice work today</div><h1>${s.tasks.length?'今日の一歩、できました。':'今は復習するものがありません。'}</h1><p>新しくわかった ${s.newSeen}こ · 自分で正解 ${s.correct}問</p><p>前に苦手だったものを思い出せた ${s.recovered}問</p><p class="muted">残り ${Math.max(0,s.tasks.length-s.index)}ステップ。復習の予定は記録に残ります。</p><div class="actions"><button class="primary" id="finish">今日はここまで</button>${s.index<s.tasks.length?'<button id="continue">もう少しつづける</button>':''}</div></div>`;$('#finish').onclick=()=>mutate(st=>{st.session=null;go('home');});if($('#continue'))$('#continue').onclick=()=>mutate(st=>{st.session.started=Date.now();st.session.answered=0;});return;}
 const task=s.tasks[s.index],c=byId.get(task.id);if(!c){tell('教材が更新されました。ホームから新しい練習を始めてください。');return;}
 let inner='';
 if(task.intro){inner=`${cardBody(c)}<div class="actions"><button class="primary" id="understood">意味と音を確かめた →</button></div><small>ここでは正解の記録はつきません。</small>`;}
 else if(s.feedback){const f=s.feedback;inner=`<div class="eyebrow">${skillLabel[task.skill]}</div><div class="feedback ${f.quality==='wrong'?'wrong':''}" role="status"><strong>${f.quality==='correct'?'✓ 思い出せた！':f.quality==='guess'?'確かめて、覚えよう。':'ここで確かめよう。'}</strong><div class="card-en" lang="en-US">${esc(c.en)}</div><p class="card-ja">${esc(c.ja)}</p><p>${esc(c.explanation)}</p><p lang="en-US">${esc(c.example)}</p><small>${esc(c.exampleJa)}</small></div>${audioButtons()}<div class="actions">${f.quality==='correct'?'<button id="guess">たまたま当たった</button>':''}<button class="primary" id="next">次へ →</button></div>`;}
 else{shownOptions=choices(c,cards,task.skill,state.progress[c.id]?.[task.skill]?.attempts||0);inner=`<div class="eyebrow">${skillLabel[task.skill]}</div><h1 style="font-size:25px">${task.skill==='listen'?'英語を聞いて、意味を選ぼう。':task.skill==='recall'?'この意味の英語はどれ？':'この英語の意味はどれ？'}</h1>${task.skill==='listen'?'<div class="visual" aria-hidden="true">♫</div>'+audioButtons(false):`<div class="card-en" ${task.skill==='read'?'lang="en-US"':''}>${esc(task.skill==='recall'?c.ja:c.en)}</div>`}<div class="quiz-options">${shownOptions.map(o=>`<button data-choice="${esc(o.id)}" ${task.skill==='recall'?'lang="en-US"':''}>${esc(o.label)}</button>`).join('')}</div><button id="unknown">わからない・答えを確かめる</button>`;}
 app.innerHTML=`<div class="narrow"><div class="study-top"><span>きょうの練習 · ${s.index+1} / ${s.tasks.length}</span><button id="pause">中断してホームへ</button></div><div class="progress-line"><span style="width:${100*s.index/Math.max(s.tasks.length,1)}%"></span></div><section class="panel card">${inner}</section><small class="muted">読む・聞く・日本語から英語の記録は別々。復習は翌日以降にも登場します。</small></div>`;
 $('#pause').onclick=()=>go('home');bindAudio(c);
 if(task.skill==='listen'&&!task.intro&&!s.feedback){const b=document.createElement('button');b.textContent='音が出ないとき：読んで練習に切り替える';b.onclick=()=>mutate(st=>{if(st.session?.id===s.id&&st.session.index===s.index)st.session.tasks[st.session.index].skill='read';});app.querySelector('section').append(b);}
 if(task.intro)$('#understood').onclick=()=>mutate(st=>{if(st.session?.id!==s.id||st.session.index!==s.index)return;if(!st.seen[c.id]){st.seen[c.id]=Date.now();st.session.newSeen++;}st.session.index++;});
 else if(s.feedback){$('#next').onclick=()=>next(s);if($('#guess'))$('#guess').onclick=()=>markGuess(s,c,task);}
 else{document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>answer(b.dataset.choice===c.id?'correct':'wrong',s,task));$('#unknown').onclick=()=>answer('wrong',s,task);}
}
function retry(st,task){
 const s=st.session,key=task.id+':'+task.skill;
 if((s.tries[key]||0)>=3||s.tasks.slice(s.index+1).some(t=>t.id===task.id&&t.skill===task.skill))return;
 let insert=s.tasks.length,otherQuestions=0;
 for(let i=s.index+1;i<s.tasks.length;i++)if(!s.tasks[i].intro&&s.tasks[i].id!==task.id&&++otherQuestions===2){insert=i+1;break;}
 s.tasks.splice(insert,0,{id:task.id,skill:task.skill});
}
async function answer(quality,s,task){audio.stop();await mutate(st=>{
 if(st.session?.id!==s.id||st.session.index!==s.index||st.session.feedback)return;
 const now=Date.now(),c=byId.get(task.id),p=st.progress[c.id]||{},old=p[task.skill],key=c.id+':'+task.skill;
 st.session.tries[key]=(st.session.tries[key]||0)+1;st.session.answered++;
 const before=structuredClone(old||null);p[task.skill]=updateProgress(old,quality,now);st.progress[c.id]=p;st.seen[c.id] ||= now;
 const recovered=quality==='correct'&&!!old?.mistakes;
 if(quality==='correct'){st.session.correct++;if(recovered)st.session.recovered++;}else retry(st,task);
 const reward=dayKey(now)+':'+c.id;if(!st.rewards.includes(reward)){st.rewards.push(reward);st.stars++;}
 const event={id:c.id,skill:task.skill,quality,at:now};st.history.push(event);
 st.session.feedback={quality,before,at:now,recovered};
 });}
function markGuess(s,c,task){mutate(st=>{if(st.session?.id!==s.id||st.session.index!==s.index||st.session.feedback?.quality!=='correct')return;const f=st.session.feedback;st.progress[c.id][task.skill]=updateProgress(f.before||{},'guess',f.at);const h=st.history.findLast(h=>h.id===c.id&&h.skill===task.skill&&h.at===f.at);if(h)h.quality='guess';f.quality='guess';st.session.correct--;if(f.recovered)st.session.recovered--;retry(st,task);});}
function next(s){mutate(st=>{if(st.session?.id!==s.id||st.session.index!==s.index||!st.session.feedback)return;st.session.index++;st.session.feedback=null;});}
function bindAudio(c){document.querySelectorAll('[data-audio]').forEach(b=>b.onclick=async()=>{try{await audio.play(c,{example:b.dataset.audio==='example',slow:b.dataset.audio==='slow'});}catch(e){tell(e.message);}});document.querySelectorAll('[data-stop]').forEach(b=>b.onclick=audio.stop);}
function autoAudio(){const s=state.session,t=s?.tasks[s.index];if(location.hash==='#study'&&state.settings.sound&&t&&(t.intro||t.skill==='listen')&&!s.feedback&&!sessionDone(s))audio.play(byId.get(t.id)).catch(e=>tell(e.message));}
function library(learned=false){app.innerHTML=`<div class="eyebrow">YOUR WORD COLLECTION</div><h1>${learned?'できるようになったもの':'ことば帳'}</h1><p class="muted">絵と例文を見て、気になることばを聞いてみよう。</p><div class="search"><input id="search" aria-label="英語や日本語を検索" placeholder="英語・日本語でさがす"><select id="theme" aria-label="テーマ"><option value="">すべてのテーマ</option>${[...new Set(cards.map(c=>c.theme))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><p id="count" class="muted"></p><div class="library" id="words"></div>`;const filter=()=>{const q=$('#search').value.trim().toLowerCase(),theme=$('#theme').value,list=cards.filter(c=>(!learned||skills.some(k=>state.progress[c.id]?.[k]?.correct))&&(!theme||c.theme===theme)&&(c.en.toLowerCase().includes(q)||c.ja.includes(q)));$('#count').textContent=list.length+'項目';$('#words').innerHTML=list.map(c=>`<button class="word-item" data-card="${c.id}"><strong lang="en-US">${esc(c.en)}</strong><span>${esc(c.ja)}</span><small>${progress(c)}</small></button>`).join('')||'<p>まだありません。少しずつ練習していこう。</p>';document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>go('card/'+b.dataset.card));};$('#search').oninput=filter;$('#theme').onchange=filter;filter();}
function detail(id){const c=byId.get(id);if(!c){go('library');return;}app.innerHTML=`<div class="narrow"><a href="#library">← ことば帳</a><section class="panel card">${cardBody(c)}<div class="actions"><button id="self">覚えた、と記録する</button><button id="test-self">絵と答えを隠して思い出す</button></div><small>「覚えた」は自分の申告。自力正解とは別に記録し、翌日また確かめます。</small></section></div>`;bindAudio(c);$('#self').onclick=()=>mutate(st=>{const now=Date.now();st.seen[id] ||= now;st.progress[id] ||= {};st.progress[id].self=updateProgress(st.progress[id].self,'self',now);st.history.push({id,skill:'self',quality:'self',at:now});tell('自分の申告として記録しました。読む・聞くの練習でも確かめよう。');});$('#test-self').onclick=()=>{app.innerHTML=`<section class="narrow panel card"><h1>${esc(c.ja)}</h1><p>英語を思い出してから、答えを見よう。</p><button id="reveal">答えをみる</button></section>`;$('#reveal').onclick=()=>detail(id);};}
function records(){const week=Date.now()-7*86400000,weekly=new Set(state.history.filter(h=>h.at>=week).map(h=>dayKey(h.at))).size;app.innerHTML=`<div class="eyebrow">LEARNING JOURNAL</div><h1>積み重ねが、力になる。</h1><div class="stats"><div class="stat"><strong>${weekly}</strong><span>この7日間の学習日</span></div><div class="stat"><strong>${Object.keys(state.seen).length}</strong><span>出会ったことば</span></div><div class="stat"><strong>${dueTasks(cards,state).length}</strong><span>復習を待つ問題</span></div></div><section class="panel"><h2>読む力と、聞く力を別々に。</h2><table><thead><tr><th>練習</th><th>自力正解 / 回答</th><th>復習待ち</th></tr></thead><tbody>${skills.map(k=>{const h=state.history.filter(h=>h.skill===k);return `<tr><td>${skillLabel[k]}</td><td>${h.filter(h=>h.quality==='correct').length} / ${h.length}</td><td>${dueTasks(cards,state).filter(t=>t.skill===k).length}</td></tr>`;}).join('')}</tbody></table><p class="muted">「定着してきた」は各技能で別日に3回以上正解し、7日以上空けた確認にも正解したことばです。自分で「覚えた」と申告した記録は正解数に含みません。</p></section><section class="panel"><h2>もう一度確かめたいテーマ</h2>${[...new Set(cards.map(c=>c.theme))].map(t=>{const h=state.history.filter(h=>byId.get(h.id)?.theme===t&&h.quality==='wrong');return h.length?`<p>${esc(t)}：これまでの誤答 ${h.length}問</p>`:'';}).join('')||'<p>練習を始めると、ここに記録されます。</p>'}</section><a href="#settings">バックアップ・学習量の設定 →</a>`;}
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const backup=()=>({app:'english-stage',version:1,createdAt:new Date().toISOString(),state});
function settings(){app.innerHTML=`<div class="narrow"><div class="eyebrow">MAKE IT YOURS</div><h1>自分のペースで。</h1><section class="panel"><div class="settings-row"><label for="new-count">1日の新しいことば<small>復習が多い日は自動で少なくします。</small></label><select id="new-count">${[3,5,10].map(n=>`<option ${n===state.settings.newCount?'selected':''} value="${n}">${n}こ</option>`).join('')}</select></div><div class="settings-row"><label for="auto-sound">カードの音声を自動で流す<small>再生ボタンはいつでも使えます。</small></label><input type="checkbox" id="auto-sound" ${state.settings.sound?'checked':''}></div><div class="settings-row"><label for="motion">動きを減らす</label><input type="checkbox" id="motion" ${!state.settings.motion?'checked':''}></div></section><section class="panel"><h2>記録を大切に保存する</h2><p class="muted">${persistent?'このブラウザの端末内に保存しています。':'一時モードです。ブラウザを閉じる前に書き出してください。'}別の端末への自動同期はありません。</p><div class="actions"><button id="export">バックアップを書き出す</button><label class="tile" for="import">バックアップを選ぶ<input id="import" type="file" accept="application/json,.json"></label></div><div id="import-preview"></div><div id="saved-backup"></div></section><p class="muted">Google Cloud Neural2の米国英語音声です。ふつう・ゆっくりの音声を用意しています。オフライン利用はまだ対応していません。</p></div>`;
 $('#new-count').onchange=e=>{const n=+e.target.value;mutate(s=>{s.settings.newCount=n;});};$('#auto-sound').onchange=e=>{const b=e.target.checked;mutate(s=>{s.settings.sound=b;});};$('#motion').onchange=e=>{const b=!e.target.checked;mutate(s=>{s.settings.motion=b;});};$('#export').onclick=()=>download(backup(),'english-stage-backup.json');
 $('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error('10MB以下のファイルを選んでください。');pendingImport=storage.validateBackup(JSON.parse(await f.text()),new Set(cards.map(c=>c.id)));$('#import-preview').innerHTML=`<p>取り込む記録：${Object.keys(pendingImport.seen).length}項目・${pendingImport.history.length}回答。現在の記録を端末内に退避してから置き換えます。</p><button id="restore" class="primary">この記録に復元する</button><button id="cancel-import">やめる</button>`;$('#cancel-import').onclick=()=>{pendingImport=null;$('#import-preview').innerHTML='';};$('#restore').onclick=async()=>{if(!pendingImport)return;const imported=pendingImport;await mutate(s=>{localStorage.setItem('english-stage-before-restore',JSON.stringify({app:'english-stage',version:1,state:s}));Object.assign(s,imported);pendingImport=null;});tell('記録を復元しました。取り込み前の記録は設定から書き出せます。');};}catch(e){tell('読み込めません：'+e.message);}};
 if(localStorage.getItem('english-stage-before-restore')){$('#saved-backup').innerHTML='<button id="old-backup">取り込み前の記録を書き出す</button>';$('#old-backup').onclick=()=>download(JSON.parse(localStorage.getItem('english-stage-before-restore')),'english-stage-before-restore.json');}
}
function alphabet(){app.innerHTML=`<div class="eyebrow">START WITH ABC</div><h1>大文字と小文字は、なかま。</h1><p>大きい A と小さい a は同じ文字。まずは見比べてみよう。</p><div class="library">${[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'].map(c=>`<div class="panel card" style="margin:0"><div class="card-en" lang="en-US">${c} ${c.toLowerCase()}</div></div>`).join('')}</div><section class="panel"><h2>文字の名前と、単語の中の音</h2><p>A の文字の名前は「エイ」。apple の最初の音とは違います。カタカナだけで覚えず、単語の音声を聞いてみよう。</p><div class="actions"><button data-alpha="g5-w-apple">A · apple を聞く</button><button data-alpha="g5-w-banana">B · banana を聞く</button><button data-alpha="g5-w-cat">C · cat を聞く</button></div></section>`;document.querySelectorAll('[data-alpha]').forEach(b=>b.onclick=()=>audio.play(byId.get(b.dataset.alpha)).catch(e=>tell(e.message)));}
function about(){app.innerHTML=`<div class="narrow panel"><h1>この教材について</h1><p>学校の英語から始める小学5年生向けの独自教材です。試用版は基本100語＋会話・表現30項目。英検の公式教材ではなく、全出題語の網羅や合格を保証するものではありません。</p><p><a href="https://www.eiken.or.jp/eiken/exam/grade_5/" target="_blank" rel="noopener">英検5級の公式案内・過去問</a>で試験形式も確認してください。</p><h2>画像</h2><p>しりとりアプリのAI生成イラストを語義と照合して参照しています。画像は同アプリの配信サーバーから読み込みます。読み込めない場合も英語・訳・例文は使えます。色・数・位置は本アプリの図を使います。</p><h2>音声</h2><p>Google Cloud Text-to-Speechの米国英語音声 en-US-Neural2-F を事前生成しています。単語と例文、それぞれにふつう・ゆっくりの音声があります。合成音声です。スマートフォン実機での再生確認は未完了です。</p><h2>記録と復習</h2><p>IndexedDBに端末内保存。自力正解で1・3・7・14・30・60日後へ。誤答・推測・自己申告は翌日に確認します。誤答は同じ回でも再登場し、1項目・技能につき最大3回です。同じ日に何回も正解しても、復習間隔は伸びません。</p><p>本人の3〜7日の試用後に、量・語義・音声・説明を調整する予定です。</p></div>`;}
function render(){audio.stop();$('#sound').textContent=state.settings.sound?'音声 ON':'音声 OFF';$('#sound').setAttribute('aria-pressed',state.settings.sound);document.body.classList.toggle('reduce-motion',!state.settings.motion);const route=location.hash.slice(1)||'home';if(route==='home')home();else if(route==='study')study();else if(route==='library'||route==='learned')library(route==='learned');else if(route.startsWith('card/'))detail(route.slice(5));else if(route==='progress')records();else if(route==='settings')settings();else if(route==='alphabet')alphabet();else if(route==='about')about();else home();document.querySelectorAll('img.picture').forEach(img=>img.onerror=()=>{img.replaceWith(Object.assign(document.createElement('p'),{textContent:'画像を読み込めません。英語と例文で確かめよう。'}));});autoAudio();}
$('#sound').onclick=()=>mutate(s=>{s.settings.sound=!s.settings.sound;});window.addEventListener('hashchange',()=>{render();app.focus({preventScroll:true});window.scrollTo(0,0);});
try{const response=await fetch('data/grade5.json');if(!response.ok)throw Error('教材の読み込みに失敗しました。再読み込みしてください。');cards=await response.json();byId=new Map(cards.map(c=>[c.id,c]));await audio.init();try{state=await storage.open();}catch{persistent=false;tell('端末に保存できないため一時モードです。設定からバックアップしてください。');}render();}catch(e){tell(e.message);app.innerHTML='<h1>教材を読み込めませんでした</h1><p>通信を確認し、ページを再読み込みしてください。</p>';}

